24	export function createService(
25	  config: Config = loadConfig(),
26	  clock: Clock = new SystemClock(),
27	): Service {
28	  const store = new MemoryStore(config.maxSamples);
29	  const queue = new IngestQueue(config.maxSamples);
30	  const router = createRouter(store, queue, config, clock);
31	
32	  return {
33	    config,
34	    store,
35	    queue,
36	    router,
37	    tick(): void {
38	      for (const sample of queue.drain()) store.put(sample);
39	      store.prune(clock.now() - config.retentionMs);
40	    },
41	  };
