47	  // reporting: the numbers below are about the store, and the store is only
48	  // current once the queue has been moved into it.
49	  service.tick();
50	  const series = service.store.series();
51	  process.stdout.write(
52	    `rollup service ready — window ${service.config.windowMs}ms, ` +
53	      `${series.length} series, ${service.queue.droppedCount()} dropped\n`,
