import { MemoryStore } from "../src/store.ts";

describe("MemoryStore construction", () => {
  it("refuses a non-positive maxPerSeries", () => {
    assert.throws(() => new MemoryStore(0, 10), RangeError);
  });

  it("refuses a non-positive maxSeries", () => {
    assert.throws(() => new MemoryStore(10, 0), RangeError);
  });
});

describe("MemoryStore series cap", () => {
  it("rejects a brand-new series once the store is at capacity", () => {
    const store = new MemoryStore(10, 2);
    store.put({ series: "a", value: 1, at: 1 });
    store.put({ series: "b", value: 1, at: 1 });
    store.put({ series: "c", value: 1, at: 1 });

    assert.deepEqual(store.series(), ["a", "b"]);
    assert.equal(store.rejectedSeries(), 1);
  });

  it("keeps accepting samples for an already-tracked series at capacity", () => {
    const store = new MemoryStore(10, 1);
    store.put({ series: "a", value: 1, at: 1 });
    store.put({ series: "a", value: 2, at: 2 });

    assert.deepEqual(
      store.range("a", 0, 10).map((s) => s.value),
      [1, 2],
    );
    assert.equal(store.rejectedSeries(), 0);
  });
});

