import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { ConfigError, DEFAULT_CONFIG, loadConfig } from "../src/config.ts";

describe("loadConfig", () => {
  it("falls back to the default series cap when unset", () => {
    const config = loadConfig({});
    assert.equal(config.maxSeries, DEFAULT_CONFIG.maxSeries);
  });

  it("reads ROLLUP_MAX_SERIES when present", () => {
    const config = loadConfig({ ROLLUP_MAX_SERIES: "5" });
    assert.equal(config.maxSeries, 5);
  });

  it("rejects a non-positive ROLLUP_MAX_SERIES", () => {
    assert.throws(() => loadConfig({ ROLLUP_MAX_SERIES: "0" }), ConfigError);
  });
});

